package mrpapermoon.whisper.utilsimport kotlinx.coroutines.currentCoroutineContextimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.flowimport kotlinx.coroutines.isActiveimport java.io.InputStreamfun InputStream.asFlow(onError: (Throwable) -> Unit = {}): Flow<ByteArray> {	return flow {		use { stream ->			val available = stream.available()			while (currentCoroutineContext().isActive && available > 0) {				val buffer = ByteArray(available)				runCatching {					stream.read(buffer)				}					.onFailure(onError)					.onSuccess {						emit(buffer)					}			}		}	}}